  const c = crewOf(M, P, r, 'brisk', T.tA + 1.4).fromTruck(T).tail(T).unload(1.6, 'bottles').fromTail(T).go(P.stepStand).go(P.step);
  const drop = c.now + 0.9; c.pose('set', 1.8, { hd: PI / 2 }).hold(null).go(P.stepStand).toTruck(T);
