  return o.strength === 'hero' || o.strength === 'pano' ? { ...k, a: Math.min(1, k.a + 0.06), glow: st.glow * 1.08 } : k;
}
/** where each DEPTH step begins (z): the near step from the quay's heroes (the lighthouse in front is nearer still: clamped) */
const DEPTH_FRONT = [228, 252, 296, 380];

/**
 * The outlines: [{ id, group: 'far'|'near', strength, roles: [main, accent], z, lines: [{ pts: [[x,y,z]…], role, closed?,
 * thin? }], power (the boot-up index group: one per building) }]. World units; the renderer projects them.
 *
 * Part 4 (the owner's review): the outlines FOLLOW THE DECO SHAPES. A tower's outline is one bent tube a side — up the shaft,
 * stepping in at every setback, over the crown's steps when the crown shares its colour, down the other side — so the
 * silhouette reads as stepped, not as stacked rectangles; thin vertical FINS (the Deco piers) run up every tier above the
 * shaft (never where a sign hangs: signRects, host → world rects); the crown is traced by its own shape.
 */
/**
 * THE DAY PASS §0 — THE DARK CORNER (the owner: right of the lighthouse a building went dark when its icon was removed): the near
 * band's blocks that reach into the lighthouse's calm zone but stand mostly CLEAR of the tower (their middle outside ±30 pt) light
 * up like their neighbours again — a warm roofline + one ledge band (nothing boxy behind the tower) and their windows (lights.js).
 * → Set of block ids (pure: the outlines + the lit windows share it).
