  const haze = clamp01(rain > 0.05 ? 0 : smooth(0.18, 0.4, cloud) * (1 - smooth(0.62, 0.8, cloud)) + smooth(0.1, 0.3, fog) * (1 - smooth(0.5, 0.75, fog)));
