  // high CIRROSTRATUS veil makes it (o.veil: clouds.js's), never a cumulus night, fog or rain)
  const halo = rain > 0.05 ? 0 : clamp01(o.veil || 0) * smooth(0.35, 0.6, m.illum == null ? 1 : m.illum);
