      x.fillStyle = `rgba(30,38,86,${(0.32 * T.day * (1 - F.fz * 0.6)).toFixed(3)})`; x.fillRect(right ? ex : ex + pw - lw, by - Math.max(0.6, 0.35 * s), lw, Math.max(1.2, 0.9 * s));
    }
