  x.fillStyle = rgb([255, 252, 242], 0.85 * k); x.fillRect(x0, y0, x1 - x0, px);                 // its lit top
  // the dentils: little stone teeth under the band, the gaps between them dark (one device px each)
  const dy = y0 + band;
