  const sh = (nk > 0.5 ? 3 : 2) * px;
  x.fillStyle = rgb([34, 22, 38], 0.4 * k); x.fillRect(x0 + px, dy + 2 * px, x1 - x0 - 2 * px, sh);
  // a frieze of soldiers (bricks on end) under it
