  const hd = (ow.hd == null ? -PI / 2 : ow.hd) + (ow.turn || 0), Fh = frameOf(o, hd), Hc = glide > 0.5 ? F(0.32 * H, 0, 0.5 * H) : Fh(0.02 * H, 0, 0.72 * H), [hx, hy] = P(cam, Hc), hR = Math.max(0.8, 0.15 * H * s);
