  c.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 6; i++) { const u = mo ? ((i / 6) + t * 0.9) % 1 : i / 6, [x, y] = pt(u), tw = mo ? 0.5 + 0.5 * Math.sin(t * 9 + i * 2.1) : 0.7;
