  const g = c.createRadialGradient(gx, gy, 0, gx, gy, w); g.addColorStop(0, `rgba(14,16,30,${(0.55 * k).toFixed(3)})`); g.addColorStop(0.7, `rgba(14,16,30,${(0.34 * k).toFixed(3)})`); g.addColorStop(1, 'rgba(14,16,30,0)');
