        // board; the outer frame that carries the bulbs a darker band of the same paint)
        if (day > 0.02) { x.fillStyle = rgba(mix(enamel, mix(pt.face, [10, 8, 14], 0.5), day)); x.beginPath(); x.roundRect(P.x, P.y, P.w, P.h, P.r); x.fill(); }
