    if (smoke.on()) { u.add('sky-high'); u.add('sky-low'); }
    if (balloons.on()) { u.add('sky-low'); if (festival) u.add('sky-high'); }
    if (air.heliOn()) u.add('sky-low');
    if (drones.on()) { u.add('sky-high'); u.add('sky-low'); u.add('water'); }
