      // comes in + goes out, a few snips now and then while the barber cuts
      const shopDay = fr.states && fr.states.shop === 'open' && (b.k ?? 0) < 0.85 && !(fr.on || []).some(e => e.id === 'shop-open');
      if (shopDay && fr.key) {
