    g.addColorStop(0, rgb(top)); g.addColorStop(Math.max(0.1, s), rgb(top)); g.addColorStop(1, rgb(top, 0));
    x.fillStyle = g;
  } else x.fillStyle = rgb(top);
  x.beginPath(); x.roundRect(tx, ay, tw, th, rad * 0.8); x.fill();
