    x.fillStyle = rgb(wet > 0.01 && o.sky ? mix(lc, o.sky, 0.4 * wet) : lc, Math.min(0.8, la) * (0.55 + o.a * 0.45));
    x.fillRect(ax + ww * 0.24, ay + hh * 0.12, ww * 0.5, Math.max(0.35, hh * 0.13));
