  else for (let i = 1; i < S.length; i++) if (el <= S[i][0]) { const [e0, c0] = S[i - 1], [e1, c1] = S[i]; const t = (el - e0) / (e1 - e0); disc = c0.map((v, j) => Math.round(lerp(v, c1[j], t))); break; }
