      const p = at(t);
      if (p && clear(p)) { clearAt = first(t - 2 * 60000, t, x => { const q = at(x); return !!q && clear(q); }); break; }
    }
  }
  return { rise, set, noonEl, startAt: Math.min(startAt, catchAt - 25 * 60000), catchAt, clearAt };
}

