  for (let d = maxD; d >= 1; d--) {
    const thin = d >= 5;
    x.fillStyle = rgb(thin ? twig : dark, thin ? 0.85 : 1);
    x.beginPath();
    let any = false;
    for (const sg of segs) {
      if (sg.d !== d) continue;
