  const L = Math.hypot(ex - ax, ey - ay) || 1, nx = -(ey - ay) / L, ny = (ex - ax) / L;
  x.moveTo(ax + nx * w0 / 2, ay + ny * w0 / 2); x.lineTo(ex + nx * w1 / 2, ey + ny * w1 / 2); x.lineTo(ex - nx * w1 / 2, ey - ny * w1 / 2); x.lineTo(ax - nx * w0 / 2, ay - ny * w0 / 2); x.closePath();
