  const nightSh = day < 0.15 ? lampShadow(ctx.lights, 1, t.x, t.z, (ctx.lampK ?? T.lamps ?? 0) * Math.min(1, n * 1.4)) : null;
  if ((day < 0.15 || (T.ovc || 0) >= 0.5) && !nightSh) return;
