export function onOutcome(fn) { listeners.add(fn); return () => listeners.delete(fn); }
export function outcomeFor(k) {
  if (outcomes.has(k)) return outcomes.get(k);
  try { const s = sessionStorage.getItem(`rc:${k}`); return s ? JSON.parse(s) : null; } catch { return null; }
}
export const pending = k => loadQueue().some(x => x.k === k);

function deliver(k, outcome) {
  outcomes.set(k, outcome);
  applyOutcome(outcome);
  try { sessionStorage.setItem(`rc:${k}`, JSON.stringify(outcome)); } catch { /* fine */ }
  for (const fn of listeners) { try { fn(k, outcome); } catch (e) { console.warn('outcome', e); } }
}

function done(k) {
  const d = loadDone().filter(x => x !== k);
  d.push(k);
  saveDone(d.slice(-60));
  saveQueue(loadQueue().filter(x => x.k !== k));
  // (CITY F — A QUEUED REPORT's PROOF: a room kept for this report (room.js — its last one out left while it was queued) closes now)
  if (globalThis.__nsSweepKept) globalThis.__nsSweepKept();
}

const backoff = n => Math.min(5 * 60_000, 2500 * 2 ** n);

const SETTLE_MAX_MS = 60_000;
export async function flush(force = false) {
  if (busy) return;
  busy = true;
  try {
    await firebaseReady;
    for (const item of loadQueue()) {
      if (!force && item.next > Date.now()) continue;
      try {
        const r = await api('report', { code: item.code, matchId: item.matchId, snap: item.snap || undefined });
        // (M4: "count it in a moment" — a player of this match was credited < 45 s ago: resend after the server's retryAfter, at most RETRY_MAX times)
        // (THE CONSOLE FIX: 'still_live' — a run of the match is still going; the SERVER's cap ends that wait, so it never uses up the tries)
        if (r.ok === false && r.retry && r.retryAfter > 0 && r.code === 'still_live') throw Object.assign(new Error(r.code), { status: 425, after: Math.min(60_000, r.retryAfter), live: true });
        if (r.ok === false && r.retry && r.retryAfter > 0 && (item.w || 0) < RETRY_MAX) throw Object.assign(new Error(r.code), { status: 425, after: Math.min(5 * 60_000, r.retryAfter) });
        if (r.ok === false && r.retry && !(r.retryAfter > 0)) throw Object.assign(new Error(r.code), { status: 425 });   // still settling: soon
        done(item.k);
        deliver(item.k, r.ok === false ? { none: true, error: r.code } : r.outcome || { none: true });
      } catch (e) {
        const permanent = e.status >= 400 && e.status < 500 && ![401, 408, 425, 429].includes(e.status);
        if (permanent) { done(item.k); deliver(item.k, { none: true, error: e.code }); continue; }
        // unreachable / busy / not final yet: try again later (sooner while the match is still settling)
        const q = loadQueue();
        const x = q.find(y => y.k === item.k);
        // (FR7 FIXES B — FR7-A's NICE line: "still settling" (425) was retried every 2 s for up to 5 h — now 2, 4, 8 … s, at most 60 s)
        if (x && e.after) { if (!e.live) x.w = (x.w || 0) + 1; x.next = Date.now() + e.after + Math.round(Math.random() * 1500); saveQueue(q); }
        else if (x) { x.n += 1; x.next = Date.now() + (e.status === 425 ? Math.min(SETTLE_MAX_MS, 2000 * 2 ** Math.max(0, x.n - 1)) : backoff(x.n)); saveQueue(q); }
      }
    }
  } finally {
    busy = false;
    schedule();
  }
}

/**
 * THE DROP A Group 0 (c) — THE LOST RUN: a solo room's BACK TO THE CITY closes (deletes) the room, and a report still waiting on its retry then
 * found nothing to check and was refused for good — that run never credited. The leave now SETTLES this match's report first: sent at once
 * (no backoff), the leave waiting until the server answered it or `ms` passed. A "count it in a moment" answer (M4 — the server holds the
 * VERIFIED match in results/{key}: api/report.js) no longer needs the room, so its later resend still credits. → true = answered
 */
export async function settle(k, ms = 3000) {
  if (!k || !pending(k)) return true;
  const until = Date.now() + ms;
  const q = loadQueue(), x = q.find(y => y.k === k);
  if (x) { x.next = 0; saveQueue(q); }
  flush(true).catch(() => {});
  while (Date.now() < until) {
    await new Promise(r => setTimeout(r, 100));
    const y = loadQueue().find(z => z.k === k);
    if (!y || (y.w || 0) > 0) return true;     // answered — or held by the server for a resend (it no longer needs the room)
    if (!busy && y.next <= Date.now()) flush(true).catch(() => {});
  }
  return !pending(k);
}

function schedule() {
  clearTimeout(timer);
  const q = loadQueue();
  if (!q.length) return;
  const next = Math.max(800, Math.min(...q.map(x => x.next || 0)) - Date.now());
  timer = setTimeout(flush, Math.min(next, 60_000));
}

export function startQueue() {
  window.addEventListener('online', () => flush(true));   // the network is back: try now, not after the backoff
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') flush(); });
  flush();
}
